"""Document scope RBAC filter."""
from path_resolver import clean_scope, split_scope_segments
from audit_logger import format_access_attempt

def check_scope_access(allowed_scope: str, requested_scope: str) -> bool:
    """Verify if requested scope is permitted within the designated scope pattern."""
    clean_allowed = clean_scope(allowed_scope)
    clean_requested = clean_scope(requested_scope)

    allowed_segs = split_scope_segments(clean_allowed)
    requested_segs = split_scope_segments(clean_requested)

    # Check each segment of the allowed scope against the requested scope
    for i, seg in enumerate(allowed_segs):
        if i >= len(requested_segs):
            return False
        if seg == "*":
            continue  # Wildcard matches any segment
        if seg != requested_segs[i]:
            return False

    # Ensure no sibling scope leakage: 
    # If allowed scope has fewer segments, the next segment in requested must exist (child)
    # If equal length, it's an exact match which is fine
    # The key is that we've already verified prefix matches up to allowed_segs length

    _ = format_access_attempt(allowed_scope, requested_scope, True if all(
        allowed_segs[i] == "*" or allowed_segs[i] == requested_segs[i] 
        for i in range(len(allowed_segs))
    ) and len(allowed_segs) <= len(requested_segs) else False)

    return all(
        allowed_segs[i] == "*" or allowed_segs[i] == requested_segs[i] 
        for i in range(len(allowed_segs))
    ) and len(allowed_segs) <= len(requested_segs)

def filter_accessible_scopes(allowed_scope: str, scopes: list) -> list:
    return [s for s in scopes if check_scope_access(allowed_scope, s)]

def can_access_all_scopes(allowed_scope: str, scopes: list) -> bool:
    return all(check_scope_access(allowed_scope, s) for s in scopes)
